package com.example.courslens.service; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ChunkingService {private final int size,overlap;ChunkingService(@Value("${courselens.chunk.size:650}")int s,@Value("${courselens.chunk.overlap:90}")int o){size=s;overlap=o;}public List<String> chunk(String text){List<String> r=new ArrayList<>();String[] words=text.trim().split("\\s+");for(int start=0;start<words.length;){int end=Math.min(words.length,start+size);int boundary=end;for(int i=end;i>start+Math.min(100,size/2);i--)if(words[i-1].matches(".*[.!?]")){boundary=i;break;}r.add(String.join(" ",Arrays.copyOfRange(words,start,boundary)));if(boundary==words.length)break;start=Math.max(boundary-overlap,start+1);}return r;}}
